package com.company.kanban.controller;
import com.company.kanban.dto.*;import com.company.kanban.entity.User;import com.company.kanban.service.TaskCheckpointService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/tasks/{taskId}/checkpoints") public class TaskCheckpointController { private final TaskCheckpointService service; public TaskCheckpointController(TaskCheckpointService service){this.service=service;} @GetMapping public List<TaskCheckpointResponse> list(@PathVariable Long taskId,@AuthenticationPrincipal User user){return service.list(taskId,user);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public TaskCheckpointResponse create(@PathVariable Long taskId,@Valid @RequestBody CreateCheckpointRequest request,@AuthenticationPrincipal User user){return service.create(taskId,request,user);} @PutMapping("/{checkpointId}") public TaskCheckpointResponse update(@PathVariable Long taskId,@PathVariable Long checkpointId,@Valid @RequestBody UpdateCheckpointRequest request,@AuthenticationPrincipal User user){return service.update(checkpointId,request,user);} @DeleteMapping("/{checkpointId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long taskId,@PathVariable Long checkpointId,@AuthenticationPrincipal User user){service.delete(checkpointId,user);} }
